import React, { useState } from 'react';
import { 
  Activity, 
  Trash2, 
  MapPin, 
  LayoutDashboard, 
  History, 
  Truck, 
  Users, 
  Settings,
  Power,
  ChevronRight
} from 'lucide-react';

const Dashboard = () => {
  // 1. STATE TO TRACK ACTIVE TAB
  const [activeTab, setActiveTab] = useState('OVERVIEW');

  // 2. DEFINE YOUR TABS
  const tabs = [
    { id: 'OVERVIEW', icon: <LayoutDashboard size={18} />, label: 'Overview' },
    { id: 'FLEET', icon: <Truck size={18} />, label: 'Fleet_Mgmt' },
    { id: 'HISTORY', icon: <History size={18} />, label: 'Log_Data' },
    { id: 'USERS', icon: <Users size={18} />, label: 'Staff_Nodes' },
  ];

  return (
    <div className="w-full max-w-[1400px] flex flex-col gap-6 p-6 animate-slot">

      {/* --- TOP HEADER WITH INTEGRATED TABS --- */}
      <div className="bg-[#AB1717] border-[6px] border-[#47510B] rounded-[30px] p-4 pb-0 red-stack-shadow flex flex-col gap-4 relative overflow-hidden">

        {/* Top Row: Logo & Status */}
        <div className="flex items-center justify-between px-4 pt-2">
          <div className="flex items-center gap-4">
            <div className="bg-[#FDFAD8] p-2 rounded-xl border-4 border-[#47510B]">
              <Activity size={24} className="text-[#AB1717]" strokeWidth={3} />
            </div>
            <h1 className="text-2xl font-black italic tracking-tighter text-[#FDFAD8] uppercase">
              TRASH<span className="text-[#CAD23C]">2</span>TRACK
            </h1>
          </div>

          <div className="flex items-center gap-3 bg-[#47510B] p-2 px-4 rounded-full border-2 border-[#CAD23C]/30">
            <div className="w-2 h-2 rounded-full bg-[#CAD23C] animate-pulse" />
            <span className="text-[10px] font-black text-[#FDFAD8] uppercase tracking-widest">System_Live</span>
          </div>
        </div>

        {/* TAB NAVIGATION ROW (The "Switches") */}
        <div className="flex gap-2 px-2 overflow-x-auto no-scrollbar">
          {tabs.map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`
                flex items-center gap-3 px-8 py-4 rounded-t-2xl font-black uppercase text-xs transition-all border-x-4 border-t-4
                ${activeTab === tab.id 
                  ? 'bg-[#FDFAD8] text-[#AB1717] border-[#47510B] translate-y-0 shadow-[0_-4px_0_0_#CAD23C]' 
                  : 'bg-[#47510B] text-[#FDFAD8] border-transparent opacity-60 hover:opacity-100 translate-y-2'}
              `}
            >
              {tab.icon}
              {tab.label}
            </button>
          ))}
        </div>
      </div>

      {/* --- DYNAMIC CONTENT AREA --- */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">

        {/* LEFT COLUMN (Static Stats) */}
        <div className="lg:col-span-3 flex flex-col gap-6">
          <div className="bg-[#A1AED1] border-[6px] border-[#47510B] rounded-[30px] p-6 yellow-stack-shadow">
            <p className="text-[11px] font-black uppercase text-[#AB1717] mb-2 tracking-tighter">Current_Module</p>
            <h2 className="text-2xl font-black text-[#47510B] italic uppercase">{activeTab}</h2>
            <div className="h-1 bg-[#47510B] w-full mt-4 opacity-20" />
          </div>

          <div className="bg-[#CAD23C] border-[6px] border-[#47510B] rounded-[30px] p-6 shadow-[8px_8px_0_0_#47510B]">
            <p className="text-[11px] font-black uppercase text-[#47510B] mb-2">Fleet_Alerts</p>
            <div className="flex items-center justify-between">
              <span className="text-4xl font-black text-[#47510B]">03</span>
              <Trash2 className="text-[#AB1717]" size={32} />
            </div>
          </div>
        </div>

        {/* MAIN PANEL: SWITCHES BASED ON STATE */}
        <div className="lg:col-span-9 bg-[#FDFAD8] border-[6px] border-[#47510B] rounded-[40px] p-8 shadow-[12px_12px_0_0_#47510B] min-h-[500px]">

          {/* TAB 1: OVERVIEW */}
          {activeTab === 'OVERVIEW' && (
            <div className="flex flex-col gap-6 animate-slot">
              <div className="flex justify-between items-center border-b-4 border-[#47510B]/10 pb-4">
                <h3 className="text-xl font-black uppercase italic text-[#AB1717]">Sector_Status</h3>
              </div>
              <div className="bg-[#A1AED1] h-80 rounded-3xl border-[6px] border-[#47510B] panel-inset-shadow relative overflow-hidden flex items-center justify-center">
                 <MapPin className="text-[#AB1717] animate-bounce" size={48} />
                 <p className="absolute bottom-4 font-black uppercase text-[#47510B]/40 text-xs italic tracking-widest">MAP_FEED_ACTIVE</p>
              </div>
            </div>
          )}

          {/* TAB 2: FLEET */}
          {activeTab === 'FLEET' && (
            <div className="flex flex-col gap-4 animate-slot">
              <h3 className="text-xl font-black uppercase italic text-[#AB1717] mb-4">Active_Fleet_Status</h3>
              {[1, 2, 3].map((truck) => (
                <div key={truck} className="bg-white border-[5px] border-[#47510B] p-5 rounded-2xl flex items-center justify-between shadow-[6px_6px_0_0_#47510B]">
                  <div className="flex items-center gap-4">
                    <Truck className="text-[#AB1717]" />
                    <span className="font-black">UNIT_0{truck}</span>
                  </div>
                  <div className="bg-[#CAD23C] px-4 py-1 rounded-full border-2 border-[#47510B] text-[10px] font-black">ON_ROUTE</div>
                  <ChevronRight size={20} />
                </div>
              ))}
            </div>
          )}

          {/* TAB 3: HISTORY */}
          {activeTab === 'HISTORY' && (
            <div className="flex flex-col gap-4 animate-slot italic">
              <h3 className="text-xl font-black uppercase text-[#AB1717]">Event_Log</h3>
              <div className="bg-[#47510B] text-[#FDFAD8] p-6 rounded-2xl font-mono text-sm leading-relaxed">
                <p>{'>'} [12:00:01] Auth: ADMIN_SESSION_START</p>
                <p>{'>'} [12:05:44] Data: NODE_22_SYMBOLOGY_SYNC</p>
                <p>{'>'} [12:10:00] Alert: WASTE_CAPACITY_EXCEEDED_S7</p>
              </div>
            </div>
          )}

           {/* TAB 4: USERS */}
           {activeTab === 'USERS' && (
            <div className="flex flex-col gap-4 animate-slot text-center py-20">
               <Users className="mx-auto text-[#AB1717] mb-4" size={64} />
               <h3 className="text-2xl font-black text-[#47510B]">STAFF_ROSTER</h3>
               <p className="uppercase text-xs font-black tracking-[0.4em] text-[#AB1717] opacity-50 italic">Access Restricted to Node Admin</p>
            </div>
          )}

        </div>
      </div>
    </div>
  );
};

export default Dashboard;
